5	// WAV 文件头结构体
6	typedef struct {
7	    char chunkID[4];       // "RIFF"
8	    uint32_t chunkSize;    // 文件大小 - 8
9	    char format[4];        // "WAVE"
10	    char subChunk1ID[4];   // "fmt "
11	    uint32_t subChunk1Size;// 16 for PCM
12	    uint16_t audioFormat;  // PCM = 1
13	    uint16_t numChannels;  // 声道数量
14	    uint32_t sampleRate;   // 采样率
15	    uint32_t byteRate;     // 采样率 * 声道数 * 每个样本的字节数
16	    uint16_t blockAlign;   // 声道数 * 每个样本的字节数
17	    uint16_t bitsPerSample;// 每个样本的位数
18	    char subChunk2ID[4];   // "data"
19	    uint32_t subChunk2Size;// 采样数据的大小
20	} WavHeader;
21	
22	void writeWavHeader(FILE *file, int numChannels, int sampleRate, int bitsPerSample, int dataSize) {
23	    WavHeader header;
24	
25	    // RIFF chunk
26	    memcpy(header.chunkID, "RIFF", 4);
27	    header.chunkSize = 36 + dataSize; // 36 + 数据块的大小
28	    memcpy(header.format, "WAVE", 4);
29	
30	    // fmt sub-chunk
31	    memcpy(header.subChunk1ID, "fmt ", 4);
32	    header.subChunk1Size = 16;        // PCM
33	    header.audioFormat = 1;           // PCM格式
34	    header.numChannels = numChannels;
35	    header.sampleRate = sampleRate;
36	    header.byteRate = sampleRate * numChannels * (bitsPerSample / 8);
37	    header.blockAlign = numChannels * (bitsPerSample / 8);
38	    header.bitsPerSample = bitsPerSample;
39	
40	    // data sub-chunk
41	    memcpy(header.subChunk2ID, "data", 4);
42	    header.subChunk2Size = dataSize;
43	
44	    // 写入 WAV 头
45	    fwrite(&header, sizeof(WavHeader), 1, file);
46	}
47	
48	int main() {
49	    // 配置 PCM 数据的参数
50	    int numChannels = 2;          // 双声道
51	    int sampleRate = 44100;       // 采样率
52	    int bitsPerSample = 16;       // 每个样本16位
53	
54	    // 打开输入的 PCM 文件
55	    FILE *pcmFile = fopen("input.pcm", "rb");
56	    if (pcmFile == NULL) {
57	        printf("无法打开 input.pcm 文件\n");
58	        return 1;
59	    }
60	
61	    // 获取 PCM 文件大小
62	    fseek(pcmFile, 0, SEEK_END);
63	    long dataSize = ftell(pcmFile);
64	    fseek(pcmFile, 0, SEEK_SET);
65	
66	    // 打开输出的 WAV 文件
67	    FILE *wavFile = fopen("output.wav", "wb");
68	    if (wavFile == NULL) {
69	        printf("无法创建 output.wav 文件\n");
70	        fclose(pcmFile);
71	        return 1;
72	    }
73	
74	    // 写 WAV 文件头
75	    writeWavHeader(wavFile, numChannels, sampleRate, bitsPerSample, dataSize);
76	
77	    // 读取 PCM 数据并写入 WAV 文件
78	    uint8_t buffer[1024];
79	    size_t bytesRead;
80	    while ((bytesRead = fread(buffer, 1, sizeof(buffer), pcmFile)) > 0) {
81	        fwrite(buffer, 1, bytesRead, wavFile);
82	    }
83	
84	    // 关闭文件
85	    fclose(pcmFile);
86	    fclose(wavFile);
87	
88	    printf("WAV 文件已生成\n");
89	    return 0;
90	}
